sys_ui_action.script:
function closeCase() {
    var text_close_case = (g_lang == "fq") ? "Fermer le cas" : "Close case";
    var text_closing_notes = (g_lang == "fq") ? "Notes de fermeture" : "Closing notes";
    var text_please_enter_closing_notes = (g_lang == "fq") ? "Veuillez entrer les notes de fermeture" : "Please enter closing notes";

    var gm = new GlideModal("glide_prompt", true, 600);
    gm.setTitle(text_close_case);
    gm.setPreference("title", text_closing_notes);
    gm.setPreference("onPromptComplete", function(value) {
        if (value == '') {
            alert(text_please_enter_closing_notes);
        } else {
            g_form.setVisible('close_notes', true);
            g_form.setValue('close_notes', value);
            gsftSubmit(null, g_form.getFormElement(), 'close_case');
        }
    });
    gm.setPreference("onPromptCancel", function(value) {
        return false; //nothing to do, cancelled
    });
    gm.render();
}

if (typeof window == 'undefined')
    serverCloseCase();

function serverCloseCase() {
    current.state = 3;
    current.update();
    action.setRedirectURL(current);

}
